g(name="Mudgee", sub="Region", state="New South Wales", zone="Central Ranges", styles=["red", "white"], dom="red",
  grapes="Shiraz, Cabernet Sauvignon, Chardonnay",
  summary="Mudgee was planted by German settlers in 1858 and was one of Australia's first regions to adopt a quality-control appellation (a voluntary scheme in 1979). Its Aboriginal name means 'nest in the hills'. Huntington Estate, Lowe and Robert Stein make generous Cabernet and Shiraz; Craigmoor's Chardonnay plantings were among Australia's oldest.",
  terroir="Altitudes from about 450 to 1,100 m on the western slopes; warm days and cool nights; red loams over clay.", producers=["Huntington Estate", "Lowe", "Robert Stein", "Logan"], nerd="Mudgee is thought to have provided one of the clones from which much Australian Chardonnay descends (the 'Mudgee clone').", contains=[])

