g(name="Swan Valley", sub="Subregion", state="Western Australia", zone="Greater Perth", styles=["white", "red", "fortified"], dom="white",
  grapes="Chenin Blanc, Verdelho, Grenache, Shiraz, Muscat, Pedro Ximénez",
  summary="Western Australia's oldest wine district, 25 minutes from Perth's centre, registered as a subregion in 2003. Thomas Waters planted Olive Farm in 1830, and Houghton (1836) became famous for its 'White Burgundy', a Chenin-based blend created by Jack Mann in 1937 that was Australia's best-selling white for decades. Croatian families such as the Kosoviches (Westfield) and Yurisiches settled here in the early twentieth century. Today it makes dry Chenin and Verdelho, fortified 'liqueur' wines and generous reds.",
  terroir="Hot (about 2,570 growing degree days) and dry, with deep alluvial loams and sands along the river.", producers=["Houghton", "Sandalford", "Faber Vineyard", "Talijancich", "Mann"],
  nerd="Houghton's White Burgundy was renamed White Classic after the EU wine agreement retired 'Burgundy' on Australian labels.", contains=[])
